const ListItem = memo(function ListItem({ label, onClick }) {
  let work = 0;
  for (let i = 0; i < 1000000; i++) work += i;
  return <li onClick={onClick}>{label} (rendered)</li>;
});

function App() {
  const [text, setText] = useState('');
  // Stable identity: same function across renders
  const handleClick = useCallback(() => alert('clicked'), []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="Type..." />
      <ul>
        <ListItem label="Item A" onClick={handleClick} />
      </ul>
    </div>
  );
}

const Counter = memo(function Counter({ onInc, count }) {
  return <button onClick={onInc}>count is {count}</button>;
});

function App() {
  const [count, setCount] = useState(0);
  const [text, setText] = useState('');
  const onInc = useCallback(() => setCount(c => c + 1), []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="Type..." />
      <Counter onInc={onInc} count={count} />
    </div>
  );
}
